@startuml

abstract class Employee {
  +socialSecurityNumber : string
  +name : string
  +emailAddress : string
}

class AdministrativeEmployee extends Employee {}

class ResearchAssistant extends Employee {
  +fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class Faculty {
  +name : string
}

class Institute {
  +name : string
  +address : string
}

class Project {
  +name : string
  +startDate : date
  +endDate : date
}

class Course {
  +id : int
  +name : string
  +weeklyDuration : int
}

class Participation {
  +hours : int
}

Faculty "1" *-- "1..*" Institute
Faculty "1" -- "0..1" Employee : leads (dean)
Institute "1..*" -- "1..*" ResearchAssistant : assigned to
ResearchAssistant "1" -- "0..*" Participation
Participation "0..*" -- "1" Project
Lecturer "1..*" -- "1..*" Course : teaches

@enduml

